macro_rules! deps {
    () => {
        DefKey!();
        DefPath!();
        DefPathData!();
        DefPathTable!();
        DisambiguatedDefPathData!();
        DisambiguatorState!();
        Definitions!();
        DefPathHashMap!();
    };
}

